namespace ghidra.file.formats.ios.dmg;



using ghidra.app.plugin.core.analysis;
using ghidra.app.plugin.core.analysis;
using ghidra.app.util.bin;
using ghidra.app.util.importer;
using ghidra.file.analyzers;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.util.exception;
using ghidra.util.task;

public class DmgAnalyzer : FileFormatAnalyzer, AnalysisWorker {

	/* @Override */
	public bool analyze(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {
		AutoAnalysisManager manager = AutoAnalysisManager.getAnalysisManager(program);
		return manager.scheduleWorker(this, null, false, monitor);
	}

	/* @Override */
	public bool analysisWorkerCallback(Program program, object workerContext, TaskMonitor monitor)
    {
		Address address = program.getMinAddress();

		ByteProvider provider = MemoryByteProvider.createProgramHeaderByteProvider(program, false);
		BinaryReader reader = new BinaryReader(provider, false);

		DmgHeader header = new DmgHeaderV2(reader);

		if (!Arrays.equals(header.getSignature(), DmgConstants.DMG_MAGIC_BYTES_v2)) {
			return false;
		}

		DataType headerDataType = header.toDataType();

		Data headerData = createData(program, address, headerDataType);

		createFragment(program, headerDataType.getName(), headerData.getMinAddress(),
			headerData.getMaxAddress().add(1));
		return true;
	}

	/* @Override */
	public string getWorkerName() {
		return getName();
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		return DmgUtil.isDMG(program);
	}

	/* @Override */
	public bool getDefaultEnablement(Program program) {
		return DmgUtil.isDMG(program);
	}

	/* @Override */
	public string getDescription() {
		return "Annotates an DMG file.";
	}

	/* @Override */
	public string getName() {
		return "DMG";
	}

	/* @Override */
	public bool isPrototype() {
		return true;
	}
}
